import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"45、【萃】 坤下兑上","description":"温公易说 - 45、【萃】 坤下兑上","frontmatter":{"title":"45、【萃】 坤下兑上","description":"温公易说 - 45、【萃】 坤下兑上"},"headers":[],"relativePath":"zh/classics/wengong/046.md","filePath":"zh/classics/wengong/046.md"}'),n={name:"zh/classics/wengong/046.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_45、【萃】-坤下兑上" tabindex="-1">45、【萃】 坤下兑上 <a class="header-anchor" href="#_45、【萃】-坤下兑上" aria-label="Permalink to “45、【萃】 坤下兑上”">​</a></h1><h3 id="彖曰-萃-聚也。顺以说-刚中而应-故聚也。王假有庙-致孝亨也。利见大人-亨聚以正也。用大牲-吉利有攸往-顺天命也。观其所聚-而天地万物之情可见矣。" tabindex="-1">彖曰：萃，聚也。顺以说，刚中而应，故聚也。王假有庙，致孝亨也。利见大人，亨聚以正也。用大牲，吉利有攸往，顺天命也。观其所聚，而天地万物之情可见矣。 <a class="header-anchor" href="#彖曰-萃-聚也。顺以说-刚中而应-故聚也。王假有庙-致孝亨也。利见大人-亨聚以正也。用大牲-吉利有攸往-顺天命也。观其所聚-而天地万物之情可见矣。" aria-label="Permalink to “彖曰：萃，聚也。顺以说，刚中而应，故聚也。王假有庙，致孝亨也。利见大人，亨聚以正也。用大牲，吉利有攸往，顺天命也。观其所聚，而天地万物之情可见矣。”">​</a></h3><p>物顺以说，萃之象也。上刚中而下应之，亦聚之象也。大人者，以正聚物者也。聚得大人，然后通也。</p><h3 id="象曰-泽上于地-萃。君子以除戎器-戒不虞。" tabindex="-1">象曰：泽上于地，萃。君子以除戎器，戒不虞。 <a class="header-anchor" href="#象曰-泽上于地-萃。君子以除戎器-戒不虞。" aria-label="Permalink to “象曰：泽上于地，萃。君子以除戎器，戒不虞。”">​</a></h3><h3 id="初六-有孚不终-乃乱乃萃。若号-一握为笑-勿恤-往无咎-象曰-乃乱乃萃-其志乱也。" tabindex="-1">初六：有孚不终，乃乱乃萃。若号，一握为笑，勿恤，往无咎 象曰：乃乱乃萃，其志乱也。 <a class="header-anchor" href="#初六-有孚不终-乃乱乃萃。若号-一握为笑-勿恤-往无咎-象曰-乃乱乃萃-其志乱也。" aria-label="Permalink to “初六：有孚不终，乃乱乃萃。若号，一握为笑，勿恤，往无咎 象曰：乃乱乃萃，其志乱也。”">​</a></h3><h3 id="六二-引吉-无咎。孚乃利用禴-象曰-引吉无咎-中未变也。" tabindex="-1">六二：引吉，无咎。孚乃利用禴 象曰：引吉无咎，中未变也。 <a class="header-anchor" href="#六二-引吉-无咎。孚乃利用禴-象曰-引吉无咎-中未变也。" aria-label="Permalink to “六二：引吉，无咎。孚乃利用禴 象曰：引吉无咎，中未变也。”">​</a></h3><h3 id="六三-萃如-嗟如-无攸利。往无咎-小吝-象曰-往无咎-上巽也。" tabindex="-1">六三：萃如，嗟如，无攸利。往无咎，小吝 象曰：往无咎，上巽也。 <a class="header-anchor" href="#六三-萃如-嗟如-无攸利。往无咎-小吝-象曰-往无咎-上巽也。" aria-label="Permalink to “六三：萃如，嗟如，无攸利。往无咎，小吝 象曰：往无咎，上巽也。”">​</a></h3><h3 id="九四-大吉无咎-象曰-大吉无咎-位不当也。" tabindex="-1">九四：大吉无咎 象曰：大吉无咎，位不当也。 <a class="header-anchor" href="#九四-大吉无咎-象曰-大吉无咎-位不当也。" aria-label="Permalink to “九四：大吉无咎 象曰：大吉无咎，位不当也。”">​</a></h3><h3 id="九五-萃有位-无咎。匪孚-元永贞-悔亡-象曰-萃有位-志未光也。" tabindex="-1">九五：萃有位，无咎。匪孚，元永贞，悔亡 象曰：萃有位，志未光也。 <a class="header-anchor" href="#九五-萃有位-无咎。匪孚-元永贞-悔亡-象曰-萃有位-志未光也。" aria-label="Permalink to “九五：萃有位，无咎。匪孚，元永贞，悔亡 象曰：萃有位，志未光也。”">​</a></h3><p>以刚中之德，仅能保位无咎，而德信不洽于民，未足光也。故必以元永贞之道聚民，然后悔亡也。</p><h3 id="上六-赍咨涕洟-无咎-象曰-赍咨涕洟-未安上也。" tabindex="-1">上六：赍咨涕洟，无咎 象曰：赍咨涕洟，未安上也。 <a class="header-anchor" href="#上六-赍咨涕洟-无咎-象曰-赍咨涕洟-未安上也。" aria-label="Permalink to “上六：赍咨涕洟，无咎 象曰：赍咨涕洟，未安上也。”">​</a></h3>',11)])])}const f=e(n,[["render",l]]);export{b as __pageData,f as default};
